def cartesian_product_numpy(*arrays):
    la = len(arrays)
    arr = np.empty([len(a) for a in arrays] + [la], dtype=arrays[0].dtype)
    for i, a in enumerate(np.ix_(*arrays)):
        arr[..., i] = a
    return arr.reshape(-1, la)

def get_homogeneous_numpy_compatible_type_of_seq(seq):
    if not seq:
        return None
    type_set = set()
    for item in seq:
        item_type = type(item)
        if item_type in PYTHON_TYPE_TO_NUMPY_TYPE:
            type_set.add(item_type)
        else:
            return None
    if len(type_set) == 1:
        return PYTHON_TYPE_TO_NUMPY_TYPE[type_set.pop()]
    elif type_set == {int, float} or type_set == {int, Decimal} or type_set == {float, Decimal} or type_set == {int, float, Decimal}:
        return np_float64
    return None
